mapper.select:
SELECT COUNT(1)
FROM exp_bid_evaluation_committee
WHERE committee_code = #{committeeCode}

    AND committee_id != #{excludeCommitteeId}

SELECT c.committee_id AS committeeId, c.tender_id AS tenderId, t.tender_name AS tenderName, c.committee_code AS committeeCode, c.committee_name AS committeeName, c.evaluation_method AS evaluationMethod, c.evaluation_location AS evaluationLocation, c.evaluation_start_time AS evaluationStartTime, c.evaluation_end_time AS evaluationEndTime, c.status AS status, d.user_name AS evaluationDirectorName, s.user_name AS supervisorName, u.user_name AS createdByName, c.created_time AS createdTime FROM exp_bid_evaluation_committee c LEFT JOIN exp_tender t ON c.tender_id = t.tender_id LEFT JOIN exp_user d ON c.evaluation_director_id = d.user_id LEFT JOIN exp_user s ON c.supervisor_id = s.user_id LEFT JOIN exp_user u ON c.created_by = u.user_id
AND c.tender_id = #{req.tenderId}
AND c.committee_code LIKE CONCAT('%', #{req.committeeCode}, '%')
AND c.committee_name LIKE CONCAT('%', #{req.committeeName}, '%')
AND c.evaluation_method = #{req.evaluationMethod}
AND c.status = #{req.status}
AND c.evaluation_director_id = #{req.evaluationDirectorId}
AND c.evaluation_start_time >= #{req.evaluationStartTimeStart}
AND c.evaluation_start_time <= #{req.evaluationStartTimeEnd}
AND c.created_by = #{req.createdBy}
AND c.created_time >= #{req.createdTimeStart}
AND c.created_time <= #{req.createdTimeEnd}
ORDER BY c.created_time DESC
